func:
msg.topic = "response";

if (msg.statusCode === 200) {
    msg.result = true;
} else {
    msg.result = false;
}

return msg;

/**
 * Builds a notification payload for the source client.
 * Only reached after a successful POST when issues need reporting.
 */
const notification = {
    payload: {
        entry_id: msg.entry.id,
        failed_files: msg.metadata.files.failed,
        entry_author: msg.entry.author,
        metadata: msg.metadata
    }
};

return notification;
